using System;
using UnityEngine;

namespace Entrenamiento.Presentation
{
    /// <summary>
    /// Logo de la app embebido para no depender de una referencia serializada.
    /// Se crea una única Texture2D en runtime y se reutiliza en las pantallas.
    /// </summary>
    public static class BrandLogo
    {
        private static Texture2D _texture;

        public static Texture2D Texture
        {
            get
            {
                if (_texture == null)
                {
                    _texture = new Texture2D(2, 2, TextureFormat.RGB24, false)
                    {
                        name = "TrainingBrandLogo",
                        filterMode = FilterMode.Bilinear,
                        wrapMode = TextureWrapMode.Clamp
                    };

                    byte[] bytes = Convert.FromBase64String(Base64Jpeg);
                    ImageConversion.LoadImage(_texture, bytes, false);
                }

                return _texture;
            }
        }

        private const string Base64Jpeg =
            "";
    }
}
